.ds-facts tbody {border-bottom: 1px solid var(--rule);}
.ds-facts tbody:hover, .ds-facts tbody[data-pinned="true"] {background: var(--sheet);}
.ds-facts .ds-line {white-space: nowrap;
  font-weight: 700;}
.ds-facts .ds-line i {margin-right: 7px;
  vertical-align: middle;}
.ds-facts .ds-date {font-family: var(--mono);
  white-space: nowrap;}
.ds-facts button {padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-align: left;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: var(--rule);
  text-underline-offset: 3px;}
.ds-facts button[aria-pressed="true"] {text-decoration-color: var(--ink);}
.ds-facts .ds-sentence td {padding: 2px 10px 8px 0;
  color: var(--ink-2);
  max-width: 75ch;}
@media (max-width: 899px) {.ds-facts {display: block;
    min-width: 0;}
.ds-facts thead {display: none;}
.ds-facts tbody {display: block;
    padding: 10px 0;}
.ds-facts tr {display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 2px 10px;}
.ds-facts td {padding: 0;}
.ds-facts tr:first-child td:nth-child(2)::after, .ds-facts tr:first-child td:nth-child(3)::after {content: " →";
    font-weight: 400;}
.ds-facts td:nth-child(5)::before {content: "valid from ";
    font-family: var(--sans);}
.ds-facts td:nth-child(6)::before {content: "invalid from ";
    font-family: var(--sans);}
.ds-facts .ds-sentence td:first-child {display: none;}
.ds-facts .ds-sentence td {padding: 2px 0 0;}}

.ds-preview [data-dim="true"] {opacity:0.16;}
.ds-preview {font: 15px/1.5 var(--sans); color: var(--ink); background: var(--ground);} :focus-visible {outline: 2px solid var(--ink);
  outline-offset: 2px;}
.ds-sections details {transition: opacity var(--step);}
.ds-sections details[data-dim="true"] {opacity: 0.45;}
.ds-sections summary i {flex: none;
  display: inline-block;
  width: 20px;
  height: 5px;
  border-radius: 2px;
  background: var(--c);}
.ds-sections details {border-top: 1px solid var(--rule);}
.ds-sections details:last-child {border-bottom: 1px solid var(--rule);}
.ds-sections summary {display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 10px;
  padding: 9px 0;
  cursor: pointer;
  list-style: none;}
.ds-sections summary::-webkit-details-marker {display: none;}
.ds-sections summary::after {content: "Show";
  margin-left: auto;
  font-size: 0.87rem;
  text-decoration: underline;
  text-underline-offset: 3px;}
.ds-sections details[open] summary::after {content: "Hide";}
.ds-sections summary i {align-self: center;}
.ds-sections summary i[data-plain="true"] {background: none;
  border: 1px solid var(--ink-2);}
.ds-sections summary span, .ds-sections summary em {font-size: 0.87rem;
  color: var(--ink-2);}
.ds-sections p {margin: 0 0 16px;
  max-width: 72ch;
  white-space: pre-wrap;}
